command:
set -e; echo CALL_STATE_BEFORE; adb shell dumpsys telephony.registry | grep -E 'mCallState=' | head -n 4; TMP=$(mktemp -d); cat > "$TMP/DownlinkCaptureProbe.java" <<'JAVA'
import android.media.AudioFormat;
import android.media.AudioRecord;
import android.media.MediaRecorder;

public final class DownlinkCaptureProbe {
  public static void main(String[] args) {
    final int sampleRate = 16000;
    final int durationMs = 2000;
    final int targetSamples = sampleRate * durationMs / 1000;
    final int channel = AudioFormat.CHANNEL_IN_MONO;
    final int encoding = AudioFormat.ENCODING_PCM_16BIT;
    int min = AudioRecord.getMinBufferSize(sampleRate, channel, encoding);
    int bufferBytes = min > 0 ? Math.max(min * 2, 4096) : 4096;
    AudioRecord record = null;
    long sumSquares = 0;
    long nonZero = 0;
    int peak = 0;
    int samplesRead = 0;
    int readErrors = 0;
    try {
      record = new AudioRecord.Builder()
          .setAudioSource(MediaRecorder.AudioSource.VOICE_DOWNLINK)
          .setAudioFormat(new AudioFormat.Builder()
              .setEncoding(encoding).setSampleRate(sampleRate).setChannelMask(channel).build())
          .setBufferSizeInBytes(bufferBytes).build();
      System.out.println("state=" + record.getState());
      System.out.println("buffer_bytes=" + bufferBytes);
      if (record.getState() != AudioRecord.STATE_INITIALIZED) { System.exit(3); }
      record.startRecording();
      System.out.println("recording_state=" + record.getRecordingState());
      short[] buf = new short[1024];
      while (samplesRead < targetSamples) {
        int want = Math.min(buf.length, targetSamples - samplesRead);
        int n = record.read(buf, 0, want, AudioRecord.READ_BLOCKING);
        if (n < 0) { readErrors++; System.out.println("read_error=" + n); break; }
        if (n == 0) continue;
        for (int i = 0; i < n; i++) {
          int v = buf[i];
          int a = Math.abs(v);
          if (a > peak) peak = a;
          if (v != 0) nonZero++;
          sumSquares += (long)v * (long)v;
        }
        samplesRead += n;
      }
      double rms = samplesRead == 0 ? 0.0 : Math.sqrt((double)sumSquares / samplesRead);
      System.out.println("samples_read=" + samplesRead);
      System.out.println("bytes_read=" + (samplesRead * 2));
      System.out.println("non_zero_samples=" + nonZero);
      System.out.println("peak=" + peak);
      System.out.println("rms=" + rms);
      System.out.println("read_errors=" + readErrors);
    } catch (Throwable t) {
      System.out.println("error=" + t.getClass().getName() + ":" + String.valueOf(t.getMessage()));
      System.exit(4);
    } finally {
      if (record != null) {
        try { if (record.getRecordingState() == AudioRecord.RECORDSTATE_RECORDING) record.stop(); } catch (Throwable ignored) {}
        try { record.release(); } catch (Throwable ignored) {}
      }
    }
  }
}
JAVA
ANDROID_JAR="$HOME/Library/Android/sdk/platforms/android-36/android.jar"; D8="$HOME/Library/Android/sdk/build-tools/36.0.0/d8"; mkdir -p "$TMP/classes"; javac -source 8 -target 8 -cp "$ANDROID_JAR" -d "$TMP/classes" "$TMP/DownlinkCaptureProbe.java"; jar cf "$TMP/classes.jar" -C "$TMP/classes" .; "$D8" --lib "$ANDROID_JAR" --output "$TMP/probe.zip" "$TMP/classes.jar"; adb push "$TMP/probe.zip" /data/local/tmp/downlink-probe.jar >/dev/null; echo CAPTURE; adb shell 'CLASSPATH=/data/local/tmp/downlink-probe.jar app_process /system/bin DownlinkCaptureProbe'; echo CALL_STATE_AFTER; adb shell dumpsys telephony.registry | grep -E 'mCallState=' | head -n 4; rm -rf "$TMP"
